CREATE TYPE "UserRole" AS ENUM ('CITIZEN', 'OPERATOR', 'ADMIN');
CREATE TYPE "BinStatus" AS ENUM ('NORMAL', 'WARNING', 'OVERFLOWING', 'OFFLINE');
CREATE TYPE "ReportStatus" AS ENUM ('OPEN', 'IN_PROGRESS', 'RESOLVED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'CITIZEN', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Bin" ("id" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "area" TEXT NOT NULL, "fillLevel" INTEGER NOT NULL DEFAULT 0, "status" "BinStatus" NOT NULL DEFAULT 'NORMAL', "latitude" DOUBLE PRECISION NOT NULL, "longitude" DOUBLE PRECISION NOT NULL, "lastSeen" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Bin_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WasteReport" ("id" TEXT NOT NULL, "category" TEXT NOT NULL, "description" TEXT NOT NULL, "area" TEXT NOT NULL, "latitude" DOUBLE PRECISION, "longitude" DOUBLE PRECISION, "status" "ReportStatus" NOT NULL DEFAULT 'OPEN', "reporterId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WasteReport_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL, "actorId" TEXT, "action" TEXT NOT NULL, "resourceType" TEXT NOT NULL, "resourceId" TEXT, "requestId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Bin_code_key" ON "Bin"("code");
CREATE INDEX "User_createdAt_idx" ON "User"("createdAt"); CREATE INDEX "Bin_status_fillLevel_idx" ON "Bin"("status","fillLevel"); CREATE INDEX "Bin_area_idx" ON "Bin"("area"); CREATE INDEX "WasteReport_status_createdAt_idx" ON "WasteReport"("status","createdAt"); CREATE INDEX "WasteReport_area_idx" ON "WasteReport"("area"); CREATE INDEX "AuditEvent_createdAt_idx" ON "AuditEvent"("createdAt"); CREATE INDEX "AuditEvent_actorId_createdAt_idx" ON "AuditEvent"("actorId","createdAt");
ALTER TABLE "WasteReport" ADD CONSTRAINT "WasteReport_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
